mapper.select:
SELECT * FROM (
    SELECT ,
        ROW_NUMBER() OVER (ORDER BY r.regdate DESC, r.daily_review_id DESC) AS rn
    FROM tbl_daily_review r JOIN tbl_member m ON m.userid = r.userid
    WHERE r.serve_date = #{serveDate,jdbcType=DATE}
) WHERE rn BETWEEN #{start} AND #{end} ORDER BY rn

SELECT 
FROM tbl_daily_review r JOIN tbl_member m ON m.userid = r.userid
WHERE r.serve_date = #{serveDate,jdbcType=DATE} AND r.userid = #{userid}

SELECT 
FROM tbl_daily_review r JOIN tbl_member m ON m.userid = r.userid
WHERE r.daily_review_id = #{reviewId}
